using Microsoft.Extensions.DependencyInjection; using w3.Domain.Interfaces; using w3.Domain.Services; using w3.Infrastructure.Repositories; namespace w3.Infrastructure; public static class DependencyInjection { public static IServiceCollection AddApplicationServices(this IServiceCollection services) { services.AddScoped<EnrollmentService>(); services.AddScoped<IStudentRepository, InMemoryStudentRepository>(); services.AddScoped<ICourseRepository, InMemoryCourseRepository>(); return services; } }
